/* avatar.js: código compartilhado do avatar (usado por avatar, perfil e comunidade).
   O avatar fica salvo no localStorage em 'trilha-avatar' como {body:'corpo1', skin:0..2}.
   Uso:  Avatar.ready(()=>{ Avatar.paintFace(elemento) })  // preenche um círculo com o rosto do avatar */
(function(){
const KEY='trilha-avatar';
const SKIN=['#835237','#f9b786','#f6e6de','#454450','#8d909c'],SKIN_N=['pele','pele','pele','golaiafi 1','golaiafi 2']; // 3 e 4 são cores especiais
const SKIN_SPECIAL=[3,4];
// Corpos em tons de cinza (preenchimento claro, contorno escuro). A cor da pele multiplica a imagem.
// face: recorte quadrado (em pixels da imagem) com cabeça e ombros, usado nos círculos pequenos.
const BODIES=[
 {id:'corpo1',n:'Corpo 1',face:{x:95,y:0,s:440},src:'data:image/png;base64,'},
 {id:'corpo2',n:'Corpo 2',face:{x:80,y:0,s:340},src:'data:image/png;base64,'}
];
// Roupas: um PNG por corpo (mesma peça, formato diferente). x,y = posição no corpo, em pixels da imagem do corpo.
// Para adicionar outra peça, crie outra entrada em CLOTHES (ex.: calca) e uma opção na aba correspondente do avatar.html.
const CLOTHES={
 camisa:{n:'Camisa',slot:'shirt',por_corpo:{
  corpo1:{x:41,y:244,src:'data:image/png;base64,'},
  corpo2:{x:59,y:200,src:'data:image/png;base64,'}}},
 calca:{n:'Calça',slot:'pants',por_corpo:{
  corpo1:{x:144,y:566,src:'data:image/png;base64,'},
  corpo2:{x:85,y:472,src:'data:image/png;base64,'}}},
 cabelo1:{n:'Cabelo 1',slot:'hair',por_corpo:{
  corpo1:{x:129,y:-23,src:'data:image/png;base64,'},
  corpo2:{x:89,y:-32,src:'data:image/png;base64,'}}},
 cabelo2:{n:'Cabelo 2',slot:'hair',por_corpo:{
  corpo1:{x:111,y:-12,src:'data:image/png;base64,'},
  corpo2:{x:81,y:-38,src:'data:image/png;base64,'}}}
};
const STAR=(x,y)=>'<path transform="translate('+x+' '+y+')" d="M0-16Q2-3 16 0Q2 3 0 16Q-2 3-16 0Q-2-3 0-16Z" fill="#8f8f95"/>';
const cache={},cv={};
function tinted(b,i){
  const k=b.id+i;if(cache[k])return cache[k];
  const w=b.img.naturalWidth,h=b.img.naturalHeight,c=document.createElement('canvas');c.width=w;c.height=h;
  const x=c.getContext('2d');x.drawImage(b.img,0,0);
  const d=x.getImageData(0,0,w,h),p=d.data,hx=SKIN[i];
  const r=parseInt(hx.slice(1,3),16),g=parseInt(hx.slice(3,5),16),bl=parseInt(hx.slice(5,7),16);
  for(let n=0;n<p.length;n+=4){const m=p[n]/255;p[n]=r*m;p[n+1]=g*m;p[n+2]=bl*m}
  x.putImageData(d,0,0);cv[k]=c;
  return cache[k]=c.toDataURL('image/png');
}
// peça de roupa do avatar (ou '' se não tiver): imagem da peça para o corpo escolhido, na escala do corpo
// peças vestidas, de baixo para cima (calça, camisa, cabelo): [{x,y,src,img}, ...]
const SLOTS=[['pants','pants'],['shirt','shirt'],['hair','hair']];
function pieces(a,b){const o=[];SLOTS.forEach(([slot,key])=>{const c=a[key]&&CLOTHES[a[key]];if(c&&c.slot===slot&&c.por_corpo[b.id])o.push(c.por_corpo[b.id])});return o}
function clothesSVG(a,b,ox,oy,s){return pieces(a,b).map(p=>'<image href="'+p.src+'" x="'+(ox+p.x*s)+'" y="'+(oy+p.y*s)+'" width="'+(p.img.naturalWidth*s)+'" height="'+(p.img.naturalHeight*s)+'"/>').join('')}
function svg(a){
  const b=BODIES.find(x=>x.id===a.body),FH=440,FW=Math.round(FH*b.img.naturalWidth/b.img.naturalHeight),FX=Math.round((400-FW)/2);
  return '<svg viewBox="0 0 400 500" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Seu avatar"><circle cx="200" cy="240" r="170" fill="#b6b6ba"/>'+STAR(52,200)+STAR(348,200)
   +'<ellipse cx="200" cy="474" rx="84" ry="8" fill="rgba(0,0,0,.25)"/><image href="'+tinted(b,a.skin)+'" x="'+FX+'" y="32" width="'+FW+'" height="'+FH+'"/>'+clothesSVG(a,b,FX,32,FH/b.img.naturalHeight)+'</svg>';
}
const fcache={};
function faceURL(a){
  const k=a.body+a.skin+(a.shirt||'')+'|'+(a.pants||'')+'|'+(a.hair||'');if(fcache[k])return fcache[k];
  const b=BODIES.find(x=>x.id===a.body),f=b.face,c=document.createElement('canvas');c.width=c.height=160;
  const x=c.getContext('2d');x.fillStyle='#b6b6ba';x.fillRect(0,0,160,160);
  tinted(b,a.skin);const q=160/f.s,ps=pieces(a,b);
  // o cabelo costuma passar do topo da cabeça: sobe o recorte o bastante para não cortá-lo
  const fy=Math.min(f.y,ps.reduce((m,p)=>Math.min(m,p.y-4),f.y));
  x.drawImage(cv[b.id+a.skin],(0-f.x)*q,(0-fy)*q,b.img.naturalWidth*q,b.img.naturalHeight*q);
  ps.forEach(p=>x.drawImage(p.img,(p.x-f.x)*q,(p.y-fy)*q,p.img.naturalWidth*q,p.img.naturalHeight*q));
  return fcache[k]=c.toDataURL('image/png');
}
// lê o avatar salvo; devolve null se o jogador ainda não escolheu nenhum
// cores bloqueadas só valem se foram compradas na loja ('trilha-loja')
const SKIN_LOCKED=[4]; // cores que precisam ser compradas na loja. A GOLAIAFI 1 (3) é grátis; a GOLAIAFI 2 (4) custa 150 de ouro (preço no CATALOG do loja.js)
function owns(skin){
  if(!SKIN_LOCKED.includes(skin))return true;
  try{const o=JSON.parse(localStorage.getItem('trilha-loja'));return !!(o&&Array.isArray(o.owned)&&o.owned.includes('pele:'+skin))}catch(e){return false}
}
function saved(){
  try{const v=JSON.parse(localStorage.getItem(KEY));
    if(v&&BODIES.some(b=>b.id===v.body)&&v.skin>=0&&v.skin<SKIN.length)return{body:v.body,skin:owns(v.skin)?v.skin:1,shirt:(v.shirt&&CLOTHES[v.shirt])?v.shirt:null,pants:(v.pants&&CLOTHES[v.pants])?v.pants:null,hair:(v.hair&&CLOTHES[v.hair]&&CLOTHES[v.hair].slot==='hair')?v.hair:null}}catch(e){}
  return null;
}
const PIECES=[];Object.values(CLOTHES).forEach(c=>Object.values(c.por_corpo).forEach(p=>PIECES.push(p)));
let ready=0,cbs=[];
function ready_(fn){ready===BODIES.length+PIECES.length?fn():cbs.push(fn)}
[...BODIES,...PIECES].forEach(b=>{b.img=new Image();b.img.onload=()=>{if(++ready===BODIES.length+PIECES.length){cbs.forEach(f=>f());cbs=[]}};b.img.src=b.src});
// Pinta o rosto do avatar salvo dentro de um círculo (.av). Sem avatar salvo, mantém a inicial do nome.
function paintFace(el){
  const a=saved();if(!a)return false;
  el.textContent='';el.style.backgroundImage='url('+faceURL(a)+')';el.style.backgroundSize='cover';el.style.backgroundPosition='center';
  el.setAttribute('aria-label','Seu avatar');return true;
}
window.Avatar={CLOTHES,KEY,SKIN,SKIN_N,SKIN_SPECIAL,owns,BODIES,tinted,svg,faceURL,saved,ready:ready_,paintFace};
})();
